```python
def split_csv_line(line: str) -> list[str]:
    result = []
    current_field = ""
    in_quotes = False
    i = 0
    while i < len(line):
        char = line[i]
        if in_quotes:
            if char == '"':
                # Check for escaped quote
                if i + 1 < len(line) and line[i+1] == '"':
                    current_field += '""'
                    i += 2
                    continue
                else:
                    current_field += '"'
                    i += 1
                    in_quotes = False
            else:
                current_field += char
        else:
            if char == '"':
                in_quotes = True
            elif char == ',':
                result.append(current_field)
                current_field = ""
                i += 1
            else:
                current_field += char
                i += 1
    # Add the last field
    result.append(current_field)
    return result
