```python
def parse_headers(raw: str) -> dict[str, str]:
    headers = {}
    for line in raw.splitlines():
        line = line.strip()
        if not line:
            continue
        if ':' not in line:
            raise ValueError(f"Line without colon: {line}")
        name_part, value_part = line.split(':', 1)
        name = name_part.strip().lower()
        value = value_part.strip()
        headers[name] = value
    return headers
