```python
def compact(n: int) -> str:
    if n < 1000:
        return f"{n:,}".replace(",", ".")
    units = [("mil", 1000), ("mi", 1_000_000), ("bi", 1_000_000_000)]
    for unit, factor in units:
        rounded = round(n / factor)  # round half up
        if n < (factor * (rounded + 1)):
            break
        else:
            return f"{rounded} {unit}"
    return str(n)
