    for node in all_nodes:
        graph[node] = []

    for item, dep_list in deps.items():
        for dep in dep_list:
            if dep in graph:  # should be
                graph[dep].append(item)  # edge from dep -> item (item depends on dep)

    # Compute in-degree: number of dependencies each node has.
    in_degree = {node: 0 for node in all_nodes}
    for item, dep_list in deps.items():
