    # Let's recompute properly:
    # For each node, in_degree = number of distinct nodes that must be before it (i.e., number of edges pointing to node). We can build reverse adjacency: for each edge dep -> item, increment in_degree[item] by 1.

    # Build reverse adjacency
    rev_in_degree = {node: 0 for node in all_nodes}
    for item, dep_list in deps.items():
        for dep in dep_list:
            rev_in_degree[item] += 1

    # Now queue nodes with zero incoming edges (no dependencies)
    heap = []
    for node in all_nodes:
        if rev_in_degree[node] == 0:
            heapq.heappush(heap, node)

    result = []
    while heap:
        current = heapq.heappop(heap)  # smallest alphabetically
        result.append(current)
        # For each node that depends on 'current' (i.e., edges from current -> other nodes), reduce their in-degree.
        for dependent in graph[current]:
            rev_in_degree[dependent] -= 1
            if rev_in_degree[dependent] == 0:
                heapq.heappush(heap, dependent)

