def wrap(text: str, width: int) -> list[str]:
    if not text.strip():
        return []
    lines = []
    current_line = []
    for word in text.split():
        if len(current_line) == 0:
            # start new line with this word
            current_line.append(word)
        else:
            # check if adding the word would exceed width including a space before it (except first word)
            if current_line and len(current_line[-1]) + 1 + len(word) <= width:
                current_line.append(word)
            else:
                lines.append(' '.join(current_line))
                current_line = [word]
    # add remaining words
    if current_line:
        lines.append(' '.join(current_line))
    return lines
