def compare_versions(a: str, b: str) -> int:
    import re

    def parse_version(ver):
        # Remove build metadata after '+'
        if '+' in ver:
            main = ver.split('+', 1)[0]
        else:
            main = ver

        # Separate pre-release part (after '-')
        if '-' in main:
            base, pre = main.split('-', 1)
        else:
            base, pre = main, ''

        parts = []
        for comp in base.split('.'):
            if comp.isdigit():
                parts.append((0, int(comp)))   # numeric
            else:
                parts.append((1, comp))       # non-numeric (alphanumeric)
        return parts, pre

    def compare_base(pA, pB):
        for pa, pb in zip(pA, pB):
            if pa != pb:
                # Different type: numeric vs alphanumeric
                if pa[0] == 0 and pb[0] == 1:
                    return -1   # pa numeric < pb alphanumeric
                elif pa[0] == 1 and pb[0] == 0:
                    return 1    # pa alphanumeric > pb numeric
                else:
                    val_a, _ = pa
                    val_b, _ = pb
                    if isinstance(val_a, int) and isinstance(val_b, int):
                        if val_a < val_b:
                            return -1
                        elif val_a > val_b:
                            return 1
                    else:
                        # both non-numeric: compare strings lexicographically
                        if val_a < val_b:
                            return -1
                        elif val_a > val_b:
                            return 1
        # All compared equal up to min length
        if len(pA) < len(pB):
            return -1
        elif len(pA) > len(pB):
            return 1
        else:
            return 0

    def compare_pre(pA, pB):
        pa = pA.split('.') if pA else []
        pb = pB.split('.') if pB else []
        for i in range(min(len(pa), len(pb))):
            a_id, b_id = pa[i], pb[i]
            a_num = a_id.isdigit()
            b_num = b_id.isdigit()
            if a_num and b_num:
                av = int(a_id)
                bv = int(b_id)
                if av < bv:
                    return -1
                elif av > bv:
                    return 1
            elif not a_num and not b_num:
                if a_id < b_id:
                    return -1
                elif a_id > b_id:
                    return 1
            else:
                # one numeric, the other alphanumeric -> numeric is lower
                if a_num and not b_num:
                    return -1   # a numeric < b alphanumeric
                elif not a_num and b_num:
                    return 1    # a alphanumeric > b numeric
        if len(pa) < len(pb):
            return -1
        elif len(pa) > len(pb):
            return 1
        else:
            return 0

    pa, pre_a = parse_version(a)
    pb, pre_b = parse_version(b)

    cmp_base = compare_base(pa, pb)
    if cmp_base != 0:
        return cmp_base

    # Handle presence of pre-release tags
    if pre_a and not pre_b:
        return -1   # version with pre-release is lower than its release
    if pre_b and not pre_a:
        return 1    # version without pre-release is higher, so a > b when b has pre

    cmp_pre = compare_pre(pre_a, pre_b)
    if cmp_pre != 0:
        return cmp_pre

    return 0
```

