def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Build adjacency list and in-degree count for all nodes (including those only as dependencies)
    graph = {}
    indegree = {}

    # Collect all items from deps keys and values
    all_nodes = set()
    for item, dep_list in deps.items():
        all_nodes.add(item)
        for dep in dep_list:
            all_nodes.add(dep)

    # Initialize graph and indegree for each node
    for node in all_nodes:
        graph[node] = []
        indegree[node] = 0

    # Populate adjacency list and update indegrees
    for item, dep_list in deps.items():
        for dep in dep_list:
            graph[dep].append(item)  # edge from dep to item (dep must come before item)
            indegree[item] += 1

    # Kahn's algorithm with a min-heap for alphabetical tie-breaking
    import heapq
    zero_indegree = [node for node in all_nodes if indegree[node] == 0]
    heapq.heapify(zero_indegree)

    result = []

    while zero_indegree:
        node = heapq.heappop(zero_indegree)
        result.append(node)

        for neighbor in graph.get(node, []):
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(zero_indegree, neighbor)

    # Check for cycles: if not all nodes are in result
    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected")

    return result
