def wrap(text: str, width: int) -> list[str]:
    if not text.strip():
        return []
    lines = []
    current_line = []
    for word in text.split():
        if len(current_line) == 0:
            # start new line with this word
            current_line.append(word)
        else:
            # check if adding the word would exceed width (including a space before it)
            if len(' ' + word) <= width:
                current_line.append(word)
            else:
                # need to finalize current line and start new one
                lines.append(' '.join(current_line))
                current_line = [word]
        # after processing all words, add the last word of current line? Actually we handle at end.
    if current_line:
        lines.append(' '.join(current_line))
    return lines
