def remove_occurrence(s: str, ch: str) -> str:
    """
    Return a new string where the first and last occurrences of character `ch` in `s`
    are removed. If there is only one occurrence or none, return the original string.
    """
    if not s or len(ch) != 1:
        return s
    # Find indices of all occurrences
    indices = [i for i, c in enumerate(s) if c == ch]
    if len(indices) <= 1:
        return s
    # Remove first and last occurrence: build new string skipping those positions
    result_chars = []
    for i, c in enumerate(s):
        if i != indices[0] and i != indices[-1]:
            result_chars.append(c)
    return ''.join(result_chars)
